e('bandrow','Direnç bandı row','back',['biceps'],'band','strength','T2e7FBboiIY',['Yere otur; sağlam, hasarsız bandı ayaklarının ortasına geçir.','Bandın kaymayacağından emin ol; gövdeni dik tut.','Dirseklerini geriye çek, omuzlarını aşağıda tut.','Kontrollü biçimde kollarını uzat.'],'Bandın yüze doğru sıyrılma riski varsa bu kurulumu kullanma.'),
e('legpress','Makinede leg press','quads',['glutes'],'legpress','strength','cDGOn-yfKJA',['Sırtını ve kalçanı mindere yasla; ayaklarını platformda omuz genişliğine yerleştir.','Makinenin güvenlik kilidini kullanım talimatına göre aç.','Belin minderden ayrılmadan dizlerini kontrollü bük.','Platformu it; dizlerini sertçe kilitleme ve set sonunda kilidi kapat.'],'İlk kullanımda salon görevlisinden makineye özel ayarları göstermesini iste.'),
e('chestpress','Makinede chest press','chest',['triceps','shoulders'],'chestpress','strength','lRo9zZ7EwpM',['Oturma yüksekliğini tutacaklar göğüs hizana gelecek şekilde ayarla.','Sırtını mindere daya, ayaklarını zemine bas.','Bileklerini düz tutarak tutacakları öne it.','Dirseklerini kilitlemeden kontrollü geri dön.'],'Omuzlarını öne yuvarlama; ağrısız hareket aralığında kal.'),
e('pulldown','Lat pulldown','back',['biceps'],'cable','strength','JGeRYIZdojU',['Uyluk desteğini sabitle, barı omuzlarından biraz geniş tut.','Gövdeni hafifçe geriye eğ; göğsünü açık tut.','Dirseklerini aşağı indirerek barı göğsünün üstüne yaklaştır.','Ağırlığı kontrollü bırak; omuzlarını aniden yukarı çekme.'],'Barı ense arkasına çekme; gövdeni sallama.'),
e('rdl','Dambıl Romanian deadlift','hamstrings',['glutes','back'],'dumbbells','strength','V8Hdl1FiNt4',['Ayakların kalça genişliğinde, dizlerin hafif bükülü başla.','Dambılları bacaklarına yakın tutup kalçanı geriye gönder.','Sırtının doğal konumunu koruyabildiğin noktaya kadar eğil.','Ayaklarınla zemine basıp kalçanı öne getirerek kalk.'],'Ağırlığı yere indirmek zorunda değilsin; önce kalçadan eğilmeyi öğren.'),
e('triceps','Kablo triseps itiş','triceps',[],'cable','strength','LXkCrxn3caQ',['Kabloyu üst konuma ayarla, tutacağı iki elle kavra.','Dirseklerini gövdenin yanında tut, dizlerini hafifçe bük.','Sadece dirseklerini açarak tutacağı aşağı it.','Üst kollarını hareket ettirmeden yavaşça başlangıca dön.'],'Omuz ve gövdeden kuvvet alarak ağırlığı savurma.'),
e('treadmill','Koşu bandında yürüyüş','calves',['quads','glutes'],'treadmill','cardio','HxsFneJFM2c',['Bant dururken üzerine çık, güvenlik klipsini giysine tak.','Düşük hızla başla; rahatladıkça tempoyu artır.','Öne bak ve dengeli, doğal adımlar at.','Hızı kademeli azalt, bant tamamen durduktan sonra in.'],'Cihazın güvenlik yönergelerini izle.','15–25 dakika'),
e('mobility','Omuz ve gövde mobilitesi','shoulders',['back'],'none','mobility','juJSkund8Q4',['Dik dur; omuzlarını yavaşça öne ve arkaya daire çizerek hareket ettir.','Kollarını ağrısız aralıkta öne ve yukarı uzat.','Kalçanı sabit tutarak gövdeni hafifçe sağa ve sola döndür.','Hareketleri zıplamadan ve nefesini tutmadan tekrarla.'],'Germeyi ağrı sınırına taşıma.','3–5 dakika')
