export const goals=[{id:'fit',name:'Fit ve dengeli',sub:'Güç, hareket ve iyi hissetmek',image:'active'},{id:'lose',name:'Yağ kaybını destekle',sub:'Daha hareketli bir yaşam',image:'cardio'},{id:'muscle',name:'Kas ve kilo kazan',sub:'Kademeli kuvvet gelişimi',image:'strength'},{id:'strong',name:'Daha güçlü ol',sub:'Kuvvet ve atletik performans',image:'strength'}];
export const plans=[{id:'start',name:'İlk Adım',days:2,pattern:[0,3],desc:'Kısa seanslarla sürdürülebilir bir başlangıç.',minutes:25},{id:'balance',name:'Dengeli Ritim',days:3,pattern:[0,2,4],desc:'Kuvvet ve dinlenme arasında kendi dengeni bul.',minutes:35},{id:'build',name:'Güçlen',days:4,pattern:[0,1,3,4],desc:'Üst ve alt vücudu ayrı günlerde çalıştır.',minutes:40},{id:'active',name:'Aktif Yaşam',days:4,pattern:[0,1,3,5],desc:'İki kuvvet, iki kardiyo günüyle hareketi çoğalt.',minutes:30}];
export function available(profile){return exercises.filter(x=>(x.equipment==='none'||profile.equipment.includes(x.equipment))&&(x.requires||[]).every(k=>profile.equipment.includes(k)));}
export const levels=[{id:'beginner',name:'Başlangıç',extra:0,description:'Temel hareketlerle başla.'},{id:'intermediate',name:'Orta',extra:1,description:'Her seansa bir hareket ekle.'},{id:'advanced',name:'İleri',extra:2,description:'Her seansa iki hareket ekle.'}];
export const planEditKey=(profile,planId,index)=>`${planId}:${profile.level||'beginner'}:${index%7}`;
export function editedWorkout(profile,workout,planId,index){
 const edit=profile.planEdits?.[planEditKey(profile,planId,index)];
 if(!edit?.items?.length||workout.rest)return workout;
 const seen=new Set(),items=[];
 for(const item of edit.items){const e=exercises.find(e=>e.id===item.id);if(!e||seen.has(e.id))continue;seen.add(e.id);const unit=/saniye|\bsn\b/.test(e.reps)?'saniye':/dakika|\bdk\b/.test(e.reps)?'dakika':'tekrar';items.push({...e,sets:Math.max(1,Math.min(6,Math.round(Number(item.sets)||1))),reps:`${Math.max(1,Math.min(120,Math.round(Number(item.reps)||10)))} ${unit}`,pairNext:!!item.pairNext});}
 if(!items.length)return workout;
 items.forEach((e,i)=>{if(i===items.length-1||i>0&&items[i-1].pairNext)e.pairNext=false;});
 const allowed=new Set(available(profile).map(e=>e.id));
 return {...workout,customized:true,exercises:items,missingEquipment:items.filter(e=>!allowed.has(e.id)).map(e=>e.id),minutes:Math.max(10,Math.round(items.reduce((sum,e)=>{const target=parseInt(e.reps)||10,work=e.reps.includes('dakika')?target:e.reps.includes('saniye')?target/60:target*3/60;return sum+e.sets*work+Math.max(0,e.sets-1)*.75;},5)))};
}
export function dayWorkout(profile,planId,index){const p=plans.find(p=>p.id===planId)||plans[1];const weekday=index%7,week=Math.floor(index/7);if(!p.pattern.includes(weekday))return{title:'Aktif dinlenme',rest:true,exercises:[],week};const slot=p.pattern.indexOf(weekday);const list=available(profile);const pick=(...ids)=>ids.map(id=>list.find(x=>x.id===id)).find(Boolean);const cardio=pick(...(slot%2?['bike','elliptical','rowing','treadmill','stairs','walk']:['treadmill','bike','elliptical','rowing','stairs','walk']));const upper=[pick('chestpress','dbbench','pushup'),pick('cablerow','pulldown','assistedpull','row','bandrow','bird'),pick('machinepress','press','lateralraise','mobility'),pick('curl','bandcurl','ezcurl','plank')];const lower=[pick('legpress','hacksquat','goblet','kettlesquat','squat'),pick('seatedcurl','legcurl','rdl','glutekick','bridge'),pick('stepup','lunge'),pick('seatedcalf','machinecalf','calf')];let selected,title;
if(p.id==='active'&&slot%2===1){selected=[cardio,pick('jacks'),pick('mobility')];title='Kardiyo & hareket';}
else if(p.id==='build'){selected=slot%2===0?upper:lower;selected.push(pick('plank'));title=slot%2===0?'Üst vücut kuvvet':'Alt vücut kuvvet';}
else{selected=[lower[0],upper[0],slot%2===0?upper[1]:lower[1],pick('plank')];title='Tüm vücut kuvvet';if(profile.goal==='muscle'||profile.goal==='strong')selected.push(pick('curl','lunge'));}
if(profile.goal==='lose'&& !selected.includes(cardio))selected.push(cardio);
selected=[...new Set(selected.filter(Boolean))];
const extra=levels.find(l=>l.id===profile.level)?.extra||0;
const ids=p.id==='active'&&slot%2===1?['bird','catcow']:p.id==='build'&&slot%2===0?['triceps','facepull','sideplank','deadbug','reversecrunch']:p.id==='build'?['abductor','adductor','bridge','sideplank','deadbug']:['bridge','facepull','calf','sideplank','deadbug'];
const more=ids.map(id=>list.find(e=>e.id===id)).filter(e=>e&&!selected.includes(e)).slice(0,extra);
selected.push(...more);
const sets=profile.level==='beginner'?(week===0?2:3):(week===3?2:3);
return editedWorkout(profile,adaptWorkout(profile,{title,rest:false,exercises:selected,week,sets,minutes:p.minutes+more.length*5+(profile.goal==='lose'&&p.id!=='active'?10:0)}),planId,index);}

